package johnsmith.enchantingoverhauled.menu.enchant.model;

import johnsmith.enchantingoverhauled.api.enchantment.EnchantmentSource;

import net.minecraft.world.item.enchantment.EnchantmentInstance;

import java.util.Optional;

/**
 * A data record that pairs a potential {@link EnchantmentInstance} with the
 * {@link EnchantmentSource} origin from which it was derived.
 * <p>
 * Used during the context building pipeline to track where an incoming
 * enchantment originated (e.g., generated by the Table vs. supplied by a Tome)
 * so the conflict resolution logic can determine the appropriate action.
 *
 * @param enchantment The proposed enchantment instance.
 * @param source      The origin source of the enchantment.
 */
public record PendingEnchantment(
        Optional<EnchantmentInstance> enchantment,
        EnchantmentSource source
) {
    // region Overrides
    /**
     * Returns a string representation of this pending enchantment, unwrapping
     * the optional for clarity in logs.
     *
     * @return The formatted string.
     */
    @Override
    public String toString() {
        String enchStr = enchantment.map(e -> e.enchantment.unwrapKey().map(k -> k.location().toString()).orElse("unknown") + " (Lvl " + e.level + ")").orElse("empty");
        return "PendingEnchantment[enchantment=" + enchStr + ", source=" + source + "]";
    }
    // endregion
}